using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using RainbowLi;
using RainbowLi.UnityGame;
using RainbowLi.EditorTools;
public static class CardDungeonChecks {
 static int checks,stage;static double start;static GameView view;static RouteMapView map;
 static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;}
 public static void Run(){try{
  for(int seed=0;seed<40;seed++){var graph=new RouteGraph(RouteGenerator.Generate(seed,4+seed%13,2+seed%4).Nodes,true,true);var run=new RouteRun(graph);while(!run.Finished){var available=graph.Nodes.Where(n=>run.CanEnter(n.id)).ToArray();Check(available.Length>0&&available.Length<=3,"one to three spatial choices");foreach(var n in graph.Nodes)Check(run.CanEnter(n.id)==(!run.Completed.Contains(n.id)&&n.floor==run.PlayerFloor+1&&(n.kind==LevelKind.Boss||Math.Abs(n.lane-run.PlayerLane)<=1)),"spatial availability");var node=available[(seed+run.Completed.Count)%available.Length];int floor=run.PlayerFloor,lane=run.PlayerLane;Check(run.Enter(node.id)&&run.PlayerFloor==floor&&run.PlayerLane==lane,"wait until encounter completes before moving");Check(!graph.Nodes.Any(n=>run.CanEnter(n.id)),"encounter occupies route");run.Complete();Check(run.PlayerFloor==node.floor&&run.PlayerLane==node.lane,"completed card becomes player position");Check(run.ChosenLane==-1,"no permanent column lock");}Check(run.Completed.Count==graph.Floors,"one card per step to exit");}
  var nodes=RouteGenerator.Generate(1,4,5).Nodes;var dungeon=new RouteRun(new RouteGraph(nodes,true,true));dungeon.Enter(1);dungeon.Complete();Check(dungeon.CanEnter(5)&&dungeon.CanEnter(6)&&dungeon.CanEnter(7),"move left then choose either direction");dungeon.Enter(7);dungeon.Complete();Check(dungeon.CanEnter(11)&&dungeon.CanEnter(13),"left and right remain available after changing column");
  var def=ScriptableObject.CreateInstance<LevelDefinition>();def.randomizeEachRun=false;def.lanes=5;def.authoredNodes=nodes;Check(LevelRouteEditorWindow.ValidateDefinition(def)==null,"valid dungeon editor");def.authoredNodes.RemoveAll(n=>n.floor==1);Check(LevelRouteEditorWindow.ValidateDefinition(def)!=null,"missing forward row rejected");UnityEngine.Object.DestroyImmediate(def);
  var legacy=new RouteRun(RouteGenerator.Generate(1));legacy.Enter(0);legacy.Complete();Check(legacy.CanEnter(3)&&!legacy.CanEnter(2),"legacy graph unchanged");
  CardDungeonSceneMigration.Run();start=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Tick;EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload;EditorApplication.EnterPlaymode();
 }catch(Exception e){Console.WriteLine("DUNGEON FAILED: "+e);EditorApplication.Exit(1);}}
 static void Log(string text,string stack,LogType type){if(stack.Contains("UnityEditor.Search.SearchDatabase"))return;if(type==LogType.Error||type==LogType.Exception){Console.WriteLine("DUNGEON FAILED: "+text+stack);EditorApplication.Exit(1);}}
 static LevelNodeView Cell(int floor,int lane)=>map.nodes.First(n=>n.authoredFloor==floor&&n.authoredLane==lane);
 static void Tick(){try{if(EditorApplication.timeSinceStartup-start>100)throw new Exception("timeout "+stage);if(!EditorApplication.isPlaying)return;view=UnityEngine.Object.FindFirstObjectByType<GameView>();map=UnityEngine.Object.FindFirstObjectByType<RouteMapView>();if(view==null||!view.IsReady||map.levels.Run==null)return;var run=map.levels.Run;var g=view.session.Game;
  if(stage==0){Check(run.Graph.CardDungeon&&run.PlayerLane==2,"dungeon starts in middle");Check(map.nodes.Count(n=>n.button.interactable)==3,"initial left middle right");Check(map.nodes.Count(n=>n.authoredFloor==0&&n.gameObject.activeSelf)==5,"full grid visible with unreachable sides dimmed");Check(map.playerMarker!=null&&map.nodePrefab.banner.pointDepth==0,"player marker and rectangular cards");Check(!map.connections.gameObject.activeSelf,"no route lines");Cell(0,0).button.onClick.Invoke();Check(g.Phase==GamePhase.Map,"distant side card rejected");Capture("01-entrance");Cell(0,3).button.onClick.Invoke();Check(g.Phase==GamePhase.Rest,"right move enters rest");Check(run.PlayerLane==2&&run.ActiveId>=0,"position waits for completion");view.progression.Leave();Check(run.PlayerLane==3&&run.PlayerFloor==0,"right card becomes position");Check(Cell(1,2).button.interactable&&Cell(1,3).button.interactable&&Cell(1,4).button.interactable,"next choice shifted right");Check(Cell(1,0).gameObject.activeSelf&&!Cell(1,0).button.interactable,"other columns retained as grid");Check(map.nodes.Where(n=>n.authoredFloor==0).All(n=>!n.gameObject.activeSelf),"past row leaves forward view");Capture("02-move-right");stage=1;return;}
  if(stage==1){Cell(1,2).button.onClick.Invoke();Check(g.Phase==GamePhase.Event,"turn left enters event");map.levels.EventGold();Check(run.PlayerLane==2&&run.PlayerFloor==1,"turn left changes position");Check(Cell(2,1).button.interactable&&Cell(2,3).button.interactable,"can turn left or right again");Capture("03-turn-left");while(!run.Finished){var n=run.Graph.Nodes.First(v=>run.CanEnter(v.id));run.Enter(n.id);run.Complete();view.session.Notify();}Check(run.Completed.Count==run.Graph.Floors,"exit reachable without clearing all columns");view.session.NewGame();Check(map.levels.Run.PlayerLane==2&&map.levels.Run.PlayerFloor==-1,"new game resets position");Console.WriteLine("PASS: "+checks+" card dungeon spatial movement, editor, lifecycle and scene checks.");EditorApplication.update-=Tick;EditorApplication.Exit(0);}
 }catch(Exception e){Console.WriteLine("DUNGEON FAILED: "+e);EditorApplication.Exit(1);}}
 static void Capture(string name){if(SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)return;var canvas=view.GetComponent<Canvas>();var mode=canvas.renderMode;var cam=UnityEngine.Object.FindFirstObjectByType<Camera>();var oldTarget=cam.targetTexture;var oldActive=RenderTexture.active;var rt=new RenderTexture(1920,1080,24);var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);try{cam.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();foreach(var t in view.GetComponentsInChildren<Text>())t.SetAllDirty();Canvas.ForceUpdateCanvases();cam.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();Directory.CreateDirectory("Assets/RainbowLi/Verification~/DungeonPreview");File.WriteAllBytes("Assets/RainbowLi/Verification~/DungeonPreview/"+name+".png",image.EncodeToPNG());}finally{RenderTexture.active=oldActive;cam.targetTexture=oldTarget;canvas.renderMode=mode;UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}
